import './boot.js';
import {home} from './home.js';
import './theme.js';
import {el,button,announce} from './ui.js';
import {mountLibrary,openArticle} from './library.js';
import {createSimulator} from './simulator.js';
import {createQuiz} from './quiz.js';
const main=document.getElementById('main');
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
const report=`<div class="wrap"><div class="page-head"><span class="eyebrow">Official channels. Prompt action.</span><h1>Report fraud. Get help.</h1><p>If money or account access is at risk, take action promptly. ScamShield is educational and does not accept reports.</p></div><div class="report-grid"><aside class="report-call"><span class="tag">India · financial cyber fraud</span><h2>1930</h2><p>Call the national financial cyber-fraud helpline to report promptly.</p><a class="button" href="tel:1930">Call 1930 ↗</a><p>Reporting promptly may help authorities act. It does not guarantee recovery of money.</p></aside><ol class="report-steps"><li><strong>Contact your bank or payment provider.</strong>Use the official app or the number on your bank card. Ask about securing your account and reporting the transaction.</li><li><strong>Report through official channels.</strong>Call 1930 for financial cyber fraud or visit the National Cyber Crime Reporting Portal.</li><li><strong>Keep relevant evidence.</strong>Save messages, transaction references, dates and other relevant records for your bank and official reporting. Do not post sensitive details publicly.</li><li><strong>Secure affected accounts.</strong>Change compromised passwords through the official app or site. Never share an OTP or pay someone promising guaranteed recovery.</li></ol></div><div class="resource"><h3>National Cyber Crime Reporting Portal</h3><p>Open the official Government of India reporting website. Check that the address is cybercrime.gov.in.</p><a class="button secondary" href="https://cybercrime.gov.in/" target="_blank" rel="noopener noreferrer">Visit cybercrime.gov.in ↗</a><p>ScamShield cannot file, track or resolve a complaint.</p></div><div class="resource"><h3>Verified sources</h3><p><a href="https://cybercrime.gov.in/uploadmedia/instructions_citizenreportingcyberfrauds.pdf" target="_blank" rel="noopener noreferrer">Official cybercrime reporting guidance ↗</a><br><a href="https://www.npci.org.in/fraud-awareness" target="_blank" rel="noopener noreferrer">NPCI payment fraud awareness ↗</a></p><small>Reporting information last verified: 25 October 2026. Follow the current instructions on the official portal.</small></div></div>`;
async function loadData(name){const response=await fetch(new URL(`../data/${name}.json`,import.meta.url));if(!response.ok)throw new Error(`Could not load ${name}`);return response.json();}
try{const [scenarios,scams,questions]=await Promise.all(['scenarios','scams','questions'].map(loadData));const simulator=createSimulator(scenarios,scams,openArticle);const quiz=createQuiz(questions,scams,openArticle);function render(){const route=location.hash.slice(1).split('/');const anchor=route[0]==='how-it-works';const page=anchor?'home':route[0]||'home';const allowed=['home','simulator','library','quiz','report'];if(!allowed.includes(page)){location.hash='home';return;}document.title=`${{home:'Spot the Scam. Stay Secure.',simulator:'Scam Simulator',library:'Scam Library',quiz:'Safety Quiz',report:'Report Fraud'}[page]} — ScamShield`;document.querySelectorAll('nav a').forEach(a=>{if(a.hash===`#${page}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(document.getElementById('article-dialog').open)document.getElementById('article-dialog').close();if(page==='home')main.innerHTML=home;else if(page==='report')main.innerHTML=report;else{main.innerHTML='<div class="wrap page-head"></div><div class="page-content"></div>';const intro=main.querySelector('.page-head');const copy={simulator:['Simulation environment / ready','Enter the fraud training lab.','Choose your category. Inspect a familiar screen. Practise a safer response in 12 fictional scenarios inspired by everyday fraud tactics.'],library:['Your everyday safety toolkit','Know the scam. Know your next move.','Explore common fraud and software threats. Find the warning signs, safer actions and steps to take if targeted.'],quiz:['Check your awareness','A quick check. A lasting habit.','Ten questions to put your learning into practice. Submit each answer for immediate feedback. Your answers stay in this tab until you reload or reset.']}[page];intro.append(el('span','eyebrow',copy[0]),el('h1','',copy[1]),el('p','',copy[2]));const content=main.querySelector('.page-content');content.className=page==='library'?'wrap section':page==='simulator'?'wrap simulator-layout':'page-layout';if(page==='simulator')simulator.mount(content,route[1]);else if(page==='quiz')quiz.mount(content);else mountLibrary(content,scams);}if(page!=='home'){const reset=button('Reset all practice progress','reset-button',()=>{simulator.reset();quiz.reset();render();announce('All simulator and quiz progress has been reset.');});main.append(reset);}document.querySelector('nav').classList.remove('open');document.querySelector('.menu-button').setAttribute('aria-expanded','false');if(anchor)document.getElementById('how-it-works')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});else window.scrollTo(0,0);main.focus({preventScroll:true});}window.addEventListener('hashchange',render);render();window.dispatchEvent(new Event('scamshield-ready'));}catch(error){main.replaceChildren(el('div','error','The learning content could not load. Please reload. If running locally, start the included server instead of opening index.html directly.'));window.dispatchEvent(new Event('scamshield-ready'));console.error(error);}
document.querySelector('.menu-button').addEventListener('click',()=>{const nav=document.getElementById('nav');const isOpen=nav.classList.toggle('open');document.querySelector('.menu-button').setAttribute('aria-expanded',String(isOpen));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelector('nav').classList.remove('open');document.querySelector('.menu-button').setAttribute('aria-expanded','false');}});
